{
  "findings": [
    {
      "check_id": "CKV_AZURE_70",
      "title": "Function App does not enforce HTTPS-only traffic",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The Function App does not set 'https_only = true', allowing data to be transmitted over unencrypted HTTP, which exposes sensitive information to interception."
    },
    {
      "check_id": "CKV_AZURE_67",
      "title": "Function App does not enforce the latest TLS/HTTP version",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The Function App does not explicitly configure 'site_config' to enforce the latest minimum TLS version (1.2), potentially allowing connections using older, insecure protocols."
    }
  ],
  "patched_code": "resource \"azurerm_function_app\" \"changeme_simple_function_app\" {\n  name                       = \"changeme-simple-function-app-name\"\n  location                   = azurerm_resource_group.changeme_simple_function_app_resource_group.location\n  resource_group_name        = azurerm_resource_group.changeme_simple_function_app_resource_group.name\n  app_service_plan_id        = azurerm_app_service_plan.changeme_simple_function_app_app_service_plan.id\n  storage_account_name       = azurerm_storage_account.changeme_simple_function_app_storage_account.name\n  storage_account_access_key = azurerm_storage_account.changeme_simple_function_app_storage_account.primary_access_key\n\n  https_only = true\n\n  site_config {\n    minimum_tls_version = \"1.2\"\n  }\n}",
  "fix_summary": "Added 'https_only = true' to enforce HTTPS-only traffic and added a 'site_config' block with 'minimum_tls_version = \"1.2\"' to ensure the Function App uses secure TLS protocols."
}
